// In Orders module: raises an event when an order is confirmed
public record OrderConfirmedEvent(Guid OrderId, Guid CustomerId, decimal Total) : INotification;

public class OrderConfirmedHandler : INotificationHandler<OrderConfirmedEvent>
{
    private readonly IEmailService _emailService;
    private readonly IInventoryService _inventoryService;

    public OrderConfirmedHandler(IEmailService emailService, IInventoryService inventoryService)
    {
        _emailService = emailService;
        _inventoryService = inventoryService;
    }

    public async Task Handle(OrderConfirmedEvent notification, CancellationToken ct)
    {
        // Both services are injected; no direct reference to Orders module
        var tasks = new[]
        {
            _emailService.SendConfirmationAsync(notification.CustomerId, notification.OrderId, ct),
            _inventoryService.ReserveAsync(notification.OrderId, ct)
        };
        await Task.WhenAll(tasks);
    }
}
